 static void shieldInput(View view){view.setClickable(true);}
 static Map<String,Object> checkInputShield(Activity activity){
  FrameLayout test=new FrameLayout(activity);final int[] behind={0};View app=new View(activity);app.setOnTouchListener(new OnTouchListener(){public boolean onTouch(View v,MotionEvent e){if(e.getActionMasked()==MotionEvent.ACTION_DOWN)behind[0]++;return true;}});test.addView(app,new FrameLayout.LayoutParams(200,200));LinearLayout shield=new LinearLayout(activity);shield.setAlpha(.3f);shieldInput(shield);test.addView(shield,new FrameLayout.LayoutParams(200,200));test.measure(View.MeasureSpec.makeMeasureSpec(200,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(200,View.MeasureSpec.EXACTLY));test.layout(0,0,200,200);
  long now=android.os.SystemClock.uptimeMillis();MotionEvent down=MotionEvent.obtain(now,now,MotionEvent.ACTION_DOWN,100,100,0),up=MotionEvent.obtain(now,now+20,MotionEvent.ACTION_UP,100,100,0);boolean accepted=test.dispatchTouchEvent(down);test.dispatchTouchEvent(up);int protectedHits=behind[0];shield.setClickable(false);test.dispatchTouchEvent(down);test.dispatchTouchEvent(up);int unprotectedHits=behind[0]-protectedHits;down.recycle();up.recycle();return Json.map("time_ms",System.currentTimeMillis(),"protected_gesture_accepted",accepted,"protected_app_hits",protectedHits,"unprotected_control_hits",unprotectedHits,"passed",accepted&&protectedHits==0&&unprotectedHits==1,"scope","Isolated Android View dispatch; no live screen touch or account interaction");
 }
 void traceBounds(){if(musicView!=null){int overlap=0;if(inputOverlay.getVisibility()==View.VISIBLE){int[] musicPosition=new int[2],inputPosition=new int[2];musicView.getLocationInWindow(musicPosition);inputOverlay.getLocationInWindow(inputPosition);overlap=Math.max(0,musicPosition[1]+musicView.getHeight()-inputPosition[1]+dp(8));}musicView.bottomInset(overlap);}if(traceOverlay==null||traceOverlay.getParent()!=scene)return;int available=scene.getHeight()-dp(12);if(inputOverlay.getVisibility()==View.VISIBLE){int[] scenePosition=new int[2],inputPosition=new int[2];scene.getLocationInWindow(scenePosition);inputOverlay.getLocationInWindow(inputPosition);available=Math.min(available,inputPosition[1]-scenePosition[1]-dp(12));}ViewGroup.LayoutParams lp=traceOverlay.getLayoutParams();int height=Math.max(0,available);if(lp.height!=height){lp.height=height;traceOverlay.setLayoutParams(lp);}if(traceBottom!=null){FrameLayout.LayoutParams bottomLp=(FrameLayout.LayoutParams)traceBottom.getLayoutParams();bottomLp.topMargin=Math.max(0,height-dp(36));traceBottom.setLayoutParams(bottomLp);}}
